fn htmlParseTryOrFinish(
    mut ctxt: htmlParserCtxtPtr,
    mut terminate: c_int,
) -> c_int {
    #[inline(always)]
    unsafe fn is_blank_ch(ch: xmlChar) -> bool {
        ch as c_int == 0x20
            || (0x9 as c_int <= ch as c_int && ch as c_int <= 0xa as c_int)
            || ch as c_int == 0xd as c_int
    }

    #[inline(always)]
    unsafe fn upper_xmlchar_like_original(ch: xmlChar) -> c_int {
        if ::core::mem::size_of::<xmlChar>() as usize > 1usize {
            toupper(ch as c_int)
        } else {
            *(*__ctype_toupper_loc()).offset(ch as isize) as c_int
        }
    }

    #[inline(always)]
    unsafe fn is_doctype_at(cur: *const xmlChar) -> bool {
        // SAFETY: caller must ensure cur points to at least 9 readable xmlChar bytes.
        *cur.offset(0) as c_int == '<' as i32
            && *cur.offset(1) as c_int == '!' as i32
            && upper_xmlchar_like_original(*cur.offset(2)) == 'D' as i32
            && upper_xmlchar_like_original(*cur.offset(3)) == 'O' as i32
            && upper_xmlchar_like_original(*cur.offset(4)) == 'C' as i32
            && upper_xmlchar_like_original(*cur.offset(5)) == 'T' as i32
            && upper_xmlchar_like_original(*cur.offset(6)) == 'Y' as i32
            && upper_xmlchar_like_original(*cur.offset(7)) == 'P' as i32
            && upper_xmlchar_like_original(*cur.offset(8)) == 'E' as i32
    }

    unsafe {
        let mut ret: c_int = 0 as c_int;
        let mut in_0: htmlParserInputPtr = ::core::ptr::null_mut::<xmlParserInput>();
        let mut avail: ptrdiff_t = 0 as ptrdiff_t;
        let mut cur: xmlChar = 0;
        let mut next: xmlChar = 0;
        let mut node_info: htmlParserNodeInfo = htmlParserNodeInfo {
            node: ::core::ptr::null::<_xmlNode>(),
            begin_pos: 0,
            begin_line: 0,
            end_pos: 0,
            end_line: 0,
        };

        loop {
            in_0 = (*ctxt).input as htmlParserInputPtr;
            if in_0.is_null() {
                break;
            }
            avail = (*in_0).end.offset_from((*in_0).cur) as c_long as ptrdiff_t;
            if avail == 0 as ptrdiff_t && terminate != 0 {
                htmlAutoCloseOnEnd(ctxt);
                if (*ctxt).nameNr == 0 as c_int
                    && (*ctxt).instate as c_int != XML_PARSER_EOF as c_int
                {
                    (*ctxt).instate = XML_PARSER_EOF;
                    let sax = (*ctxt).sax;
                    if !sax.is_null() && (*sax).endDocument.is_some() {
                        (*sax).endDocument.expect("non-null function pointer")((*ctxt).userData);
                    }
                }
            }
            if avail < 1 as ptrdiff_t {
                break;
            }

            cur = *(*in_0).cur.offset(0);
            if cur as c_int == 0 as c_int {
                (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(1);
                (*(*ctxt).input).col += 1 as c_int;
                continue;
            }

            match (*ctxt).instate as c_int {
                -1 => {
                    break;
                }
                0 => {
                    if (*(*ctxt).input).flags as c_uint & XML_INPUT_HAS_ENCODING == 0 as c_uint
                        && xmlStrncmp(
                            (*(*ctxt).input).cur,
                            b"<?xm\0" as *const u8 as *const c_char as *mut xmlChar,
                            4 as c_int,
                        ) == 0 as c_int
                    {
                        xmlSwitchEncoding(ctxt as xmlParserCtxtPtr, XML_CHAR_ENCODING_UTF8);
                    }
                    cur = *(*in_0).cur.offset(0);
                    if is_blank_ch(cur) {
                        htmlSkipBlankChars(ctxt as xmlParserCtxtPtr);
                        avail = (*in_0).end.offset_from((*in_0).cur) as c_long as ptrdiff_t;
                    }
                    let sax = (*ctxt).sax;
                    if !sax.is_null() && (*sax).setDocumentLocator.is_some() {
                        (*sax).setDocumentLocator.expect("non-null function pointer")(
                            (*ctxt).userData,
                            __xmlDefaultSAXLocator(),
                        );
                    }
                    if !sax.is_null()
                        && (*sax).startDocument.is_some()
                        && (*ctxt).disableSAX == 0
                    {
                        (*sax).startDocument.expect("non-null function pointer")((*ctxt).userData);
                    }
                    if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                        break;
                    }
                    cur = *(*in_0).cur.offset(0);
                    next = *(*in_0).cur.offset(1);
                    if cur as c_int == '<' as i32
                        && next as c_int == '!' as i32
                        && is_doctype_at((*(*ctxt).input).cur)
                    {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                1 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        htmlParseDocTypeDecl(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_PROLOG;
                    } else {
                        (*ctxt).instate = XML_PARSER_MISC;
                    }
                }
                1 => {
                    htmlSkipBlankChars(ctxt as xmlParserCtxtPtr);
                    avail = (*in_0).end.offset_from((*in_0).cur) as c_long as ptrdiff_t;
                    if avail < 1 as ptrdiff_t {
                        break;
                    }
                    if avail < 2 as ptrdiff_t {
                        if terminate == 0 {
                            break;
                        }
                        next = ' ' as i32 as xmlChar;
                    } else {
                        next = *(*in_0).cur.offset(1);
                    }
                    cur = *(*in_0).cur.offset(0);
                    if cur as c_int == '<' as i32
                        && next as c_int == '!' as i32
                        && *(*in_0).cur.offset(2) as c_int == '-' as i32
                        && *(*in_0).cur.offset(3) as c_int == '-' as i32
                    {
                        if terminate == 0 && htmlParseLookupCommentEnd(ctxt) < 0 as c_int {
                            break;
                        }
                        htmlParseComment(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_MISC;
                    } else if cur as c_int == '<' as i32 && next as c_int == '?' as i32 {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                0 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        htmlParsePI(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_MISC;
                    } else if cur as c_int == '<' as i32
                        && next as c_int == '!' as i32
                        && is_doctype_at((*(*ctxt).input).cur)
                    {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                1 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        htmlParseDocTypeDecl(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_PROLOG;
                    } else {
                        if cur as c_int == '<' as i32
                            && next as c_int == '!' as i32
                            && avail < 9 as ptrdiff_t
                        {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_CONTENT;
                    }
                }
                4 => {
                    htmlSkipBlankChars(ctxt as xmlParserCtxtPtr);
                    avail = (*in_0).end.offset_from((*in_0).cur) as c_long as ptrdiff_t;
                    if avail < 2 as ptrdiff_t {
                        break;
                    }
                    cur = *(*in_0).cur.offset(0);
                    next = *(*in_0).cur.offset(1);
                    if cur as c_int == '<' as i32
                        && next as c_int == '!' as i32
                        && *(*in_0).cur.offset(2) as c_int == '-' as i32
                        && *(*in_0).cur.offset(3) as c_int == '-' as i32
                    {
                        if terminate == 0 && htmlParseLookupCommentEnd(ctxt) < 0 as c_int {
                            break;
                        }
                        htmlParseComment(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_PROLOG;
                    } else if cur as c_int == '<' as i32 && next as c_int == '?' as i32 {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                0 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        htmlParsePI(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_PROLOG;
                    } else {
                        if cur as c_int == '<' as i32
                            && next as c_int == '!' as i32
                            && avail < 4 as ptrdiff_t
                        {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_CONTENT;
                    }
                }
                14 => {
                    avail = (*in_0).end.offset_from((*in_0).cur) as c_long as ptrdiff_t;
                    if avail < 1 as ptrdiff_t {
                        break;
                    }
                    cur = *(*in_0).cur.offset(0);
                    if is_blank_ch(cur) {
                        htmlParseCharData(ctxt);
                        break;
                    } else {
                        if avail < 2 as ptrdiff_t {
                            break;
                        }
                        next = *(*in_0).cur.offset(1);
                        if cur as c_int == '<' as i32
                            && next as c_int == '!' as i32
                            && *(*in_0).cur.offset(2) as c_int == '-' as i32
                            && *(*in_0).cur.offset(3) as c_int == '-' as i32
                        {
                            if terminate == 0 && htmlParseLookupCommentEnd(ctxt) < 0 as c_int {
                                break;
                            }
                            htmlParseComment(ctxt);
                            if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                break;
                            }
                            (*ctxt).instate = XML_PARSER_EPILOG;
                        } else if cur as c_int == '<' as i32 && next as c_int == '?' as i32 {
                            if terminate == 0
                                && htmlParseLookupSequence(
                                    ctxt,
                                    '>' as i32 as xmlChar,
                                    0 as xmlChar,
                                    0 as xmlChar,
                                    0 as c_int,
                                ) < 0 as c_int
                            {
                                break;
                            }
                            htmlParsePI(ctxt);
                            if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                break;
                            }
                            (*ctxt).instate = XML_PARSER_EPILOG;
                        } else {
                            if cur as c_int == '<' as i32
                                && next as c_int == '!' as i32
                                && avail < 4 as ptrdiff_t
                            {
                                break;
                            }
                            (*ctxt).errNo = XML_ERR_DOCUMENT_END as c_int;
                            (*ctxt).wellFormed = 0 as c_int;
                            (*ctxt).instate = XML_PARSER_EOF;
                            let sax = (*ctxt).sax;
                            if !sax.is_null() && (*sax).endDocument.is_some() {
                                (*sax).endDocument.expect("non-null function pointer")(
                                    (*ctxt).userData,
                                );
                            }
                            break;
                        }
                    }
                }
                6 => {
                    let mut name: *const xmlChar = ::core::ptr::null::<xmlChar>();
                    let mut failed: c_int = 0;
                    let mut info: *const htmlElemDesc = ::core::ptr::null::<htmlElemDesc>();
                    if avail < 1 as ptrdiff_t {
                        break;
                    }
                    if avail < 2 as ptrdiff_t {
                        if terminate == 0 {
                            break;
                        }
                        next = ' ' as i32 as xmlChar;
                    } else {
                        next = *(*in_0).cur.offset(1);
                    }
                    cur = *(*in_0).cur.offset(0);
                    if cur as c_int != '<' as i32 {
                        (*ctxt).instate = XML_PARSER_CONTENT;
                    } else if next as c_int == '/' as i32 {
                        (*ctxt).instate = XML_PARSER_END_TAG;
                        (*ctxt).checkIndex = 0 as c_long;
                    } else {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                1 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        if (*ctxt).record_info != 0 {
                            node_info.begin_pos = (*(*ctxt).input).consumed.wrapping_add(
                                (*(*ctxt).input).cur.offset_from((*(*ctxt).input).base) as c_long
                                    as c_ulong,
                            );
                            node_info.begin_line = (*(*ctxt).input).line as c_ulong;
                        }
                        failed = htmlParseStartTag(ctxt);
                        name = (*ctxt).name;
                        if failed == -(1 as c_int) || name.is_null() {
                            if *(*(*ctxt).input).cur as c_int == '>' as i32 {
                                xmlNextChar(ctxt as xmlParserCtxtPtr);
                            }
                        } else {
                            info = htmlTagLookup(name);
                            if info.is_null() {
                                htmlParseErr(
                                    ctxt as xmlParserCtxtPtr,
                                    XML_HTML_UNKNOWN_TAG,
                                    b"Tag %s invalid\n\0" as *const u8 as *const c_char,
                                    name,
                                    ::core::ptr::null::<xmlChar>(),
                                );
                            }
                            if *(*(*ctxt).input).cur as c_int == '/' as i32
                                && *(*(*ctxt).input).cur.offset(1) as c_int == '>' as i32
                            {
                                (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(2);
                                (*(*ctxt).input).col += 2 as c_int;
                                let sax = (*ctxt).sax;
                                if !sax.is_null() && (*sax).endElement.is_some() {
                                    (*sax).endElement.expect("non-null function pointer")(
                                        (*ctxt).userData,
                                        name,
                                    );
                                }
                                htmlnamePop(ctxt);
                                if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                    break;
                                }
                                (*ctxt).instate = XML_PARSER_CONTENT;
                            } else if *(*(*ctxt).input).cur as c_int == '>' as i32 {
                                xmlNextChar(ctxt as xmlParserCtxtPtr);
                                if !info.is_null() && (*info).empty as c_int != 0 {
                                    let sax = (*ctxt).sax;
                                    if !sax.is_null() && (*sax).endElement.is_some() {
                                        (*sax).endElement.expect("non-null function pointer")(
                                            (*ctxt).userData,
                                            name,
                                        );
                                    }
                                    htmlnamePop(ctxt);
                                }
                                if (*ctxt).record_info != 0 {
                                    htmlNodeInfoPush(ctxt, &raw mut node_info);
                                }
                                if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                    break;
                                }
                                (*ctxt).instate = XML_PARSER_CONTENT;
                            } else {
                                htmlParseErr(
                                    ctxt as xmlParserCtxtPtr,
                                    XML_ERR_GT_REQUIRED,
                                    b"Couldn't find end of Start Tag %s\n\0" as *const u8
                                        as *const c_char,
                                    name,
                                    ::core::ptr::null::<xmlChar>(),
                                );
                                if xmlStrEqual(name, (*ctxt).name) != 0 {
                                    nodePop(ctxt as xmlParserCtxtPtr);
                                    htmlnamePop(ctxt);
                                }
                                if (*ctxt).record_info != 0 {
                                    htmlNodeInfoPush(ctxt, &raw mut node_info);
                                }
                                if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                    break;
                                }
                                (*ctxt).instate = XML_PARSER_CONTENT;
                            }
                        }
                    }
                }
                7 => {
                    let mut chr: [xmlChar; 2] = [0 as c_int as xmlChar, 0 as c_int as xmlChar];
                    if (*ctxt).token != 0 as c_int {
                        chr[0] = (*ctxt).token as xmlChar;
                        htmlCheckParagraph(ctxt);
                        let sax = (*ctxt).sax;
                        if !sax.is_null() && (*sax).characters.is_some() {
                            (*sax).characters.expect("non-null function pointer")(
                                (*ctxt).userData,
                                &raw mut chr as *mut xmlChar,
                                1 as c_int,
                            );
                        }
                        (*ctxt).token = 0 as c_int;
                        (*ctxt).checkIndex = 0 as c_long;
                    }
                    if avail == 1 as ptrdiff_t && terminate != 0 {
                        cur = *(*in_0).cur.offset(0);
                        if cur as c_int != '<' as i32 && cur as c_int != '&' as i32 {
                            let sax = (*ctxt).sax;
                            if !sax.is_null() {
                                chr[0] = cur;
                                if is_blank_ch(cur) {
                                    if (*ctxt).keepBlanks != 0 {
                                        if (*sax).characters.is_some() {
                                            (*sax).characters.expect("non-null function pointer")(
                                                (*ctxt).userData,
                                                &raw mut chr as *mut xmlChar,
                                                1 as c_int,
                                            );
                                        }
                                    } else if (*sax).ignorableWhitespace.is_some() {
                                        (*sax)
                                            .ignorableWhitespace
                                            .expect("non-null function pointer")(
                                            (*ctxt).userData,
                                            &raw mut chr as *mut xmlChar,
                                            1 as c_int,
                                        );
                                    }
                                } else {
                                    htmlCheckParagraph(ctxt);
                                    if (*sax).characters.is_some() {
                                        (*sax).characters.expect("non-null function pointer")(
                                            (*ctxt).userData,
                                            &raw mut chr as *mut xmlChar,
                                            1 as c_int,
                                        );
                                    }
                                }
                            }
                            (*ctxt).token = 0 as c_int;
                            (*ctxt).checkIndex = 0 as c_long;
                            (*in_0).cur = (*in_0).cur.offset(1);
                            continue;
                        }
                    }
                    if avail < 2 as ptrdiff_t {
                        break;
                    }
                    cur = *(*in_0).cur.offset(0);
                    next = *(*in_0).cur.offset(1);

                    if xmlStrEqual(
                        (*ctxt).name,
                        b"script\0" as *const u8 as *const c_char as *mut xmlChar,
                    ) != 0
                        || xmlStrEqual(
                            (*ctxt).name,
                            b"style\0" as *const u8 as *const c_char as *mut xmlChar,
                        ) != 0
                    {
                        if terminate == 0 {
                            let mut idx: c_int;
                            let mut val: xmlChar;
                            idx = htmlParseLookupSequence(
                                ctxt,
                                '<' as i32 as xmlChar,
                                '/' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as c_int,
                            );
                            if idx < 0 as c_int {
                                break;
                            }
                            val = *(*in_0).cur.offset((idx + 2 as c_int) as isize);
                            if val as c_int == 0 as c_int {
                                (*ctxt).checkIndex = idx as c_long;
                                break;
                            }
                        }
                        htmlParseScript(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        if !(cur as c_int == '<' as i32 && next as c_int == '/' as i32) {
                            continue;
                        }
                        (*ctxt).instate = XML_PARSER_END_TAG;
                        (*ctxt).checkIndex = 0 as c_long;
                    } else if cur as c_int == '<' as i32 && next as c_int == '!' as i32 {
                        if avail < 4 as ptrdiff_t {
                            break;
                        }
                        if is_doctype_at((*(*ctxt).input).cur) {
                            if terminate == 0
                                && htmlParseLookupSequence(
                                    ctxt,
                                    '>' as i32 as xmlChar,
                                    0 as xmlChar,
                                    0 as xmlChar,
                                    1 as c_int,
                                ) < 0 as c_int
                            {
                                break;
                            }
                            htmlParseErr(
                                ctxt as xmlParserCtxtPtr,
                                XML_HTML_STRUCURE_ERROR,
                                b"Misplaced DOCTYPE declaration\n\0" as *const u8
                                    as *const c_char,
                                b"DOCTYPE\0" as *const u8 as *const c_char as *mut xmlChar,
                                ::core::ptr::null::<xmlChar>(),
                            );
                            htmlParseDocTypeDecl(ctxt);
                        } else if *(*in_0).cur.offset(2) as c_int == '-' as i32
                            && *(*in_0).cur.offset(3) as c_int == '-' as i32
                        {
                            if terminate == 0 && htmlParseLookupCommentEnd(ctxt) < 0 as c_int {
                                break;
                            }
                            htmlParseComment(ctxt);
                            if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                                break;
                            }
                            (*ctxt).instate = XML_PARSER_CONTENT;
                        } else {
                            if terminate == 0
                                && htmlParseLookupSequence(
                                    ctxt,
                                    '>' as i32 as xmlChar,
                                    0 as xmlChar,
                                    0 as xmlChar,
                                    0 as c_int,
                                ) < 0 as c_int
                            {
                                break;
                            }
                            htmlSkipBogusComment(ctxt);
                        }
                    } else if cur as c_int == '<' as i32 && next as c_int == '?' as i32 {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '>' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                0 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        htmlParsePI(ctxt);
                        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_CONTENT;
                    } else if cur as c_int == '<' as i32 && next as c_int == '/' as i32 {
                        (*ctxt).instate = XML_PARSER_END_TAG;
                        (*ctxt).checkIndex = 0 as c_long;
                    } else if cur as c_int == '<' as i32
                        && ((0x41 as c_int <= next as c_int && next as c_int <= 0x5a as c_int)
                            || (0x61 as c_int <= next as c_int
                                && next as c_int <= 0x7a as c_int))
                    {
                        if terminate == 0 && next as c_int == 0 as c_int {
                            break;
                        }
                        (*ctxt).instate = XML_PARSER_START_TAG;
                        (*ctxt).checkIndex = 0 as c_long;
                    } else if cur as c_int == '<' as i32 {
                        let sax = (*ctxt).sax;
                        if !sax.is_null()
                            && (*ctxt).disableSAX == 0
                            && (*sax).characters.is_some()
                        {
                            (*sax).characters.expect("non-null function pointer")(
                                (*ctxt).userData,
                                b"<\0" as *const u8 as *const c_char as *mut xmlChar,
                                1 as c_int,
                            );
                        }
                        xmlNextChar(ctxt as xmlParserCtxtPtr);
                    } else {
                        if terminate == 0
                            && htmlParseLookupSequence(
                                ctxt,
                                '<' as i32 as xmlChar,
                                0 as xmlChar,
                                0 as xmlChar,
                                0 as c_int,
                            ) < 0 as c_int
                        {
                            break;
                        }
                        (*ctxt).checkIndex = 0 as c_long;
                        while (*ctxt).instate as c_int != XML_PARSER_EOF as c_int
                            && cur as c_int != '<' as i32
                            && (*in_0).cur < (*in_0).end
                        {
                            if cur as c_int == '&' as i32 {
                                htmlParseReference(ctxt);
                            } else {
                                htmlParseCharData(ctxt);
                            }
                            cur = *(*in_0).cur.offset(0);
                        }
                    }
                }
                9 => {
                    if avail < 2 as ptrdiff_t {
                        break;
                    }
                    if terminate == 0
                        && htmlParseLookupSequence(
                            ctxt,
                            '>' as i32 as xmlChar,
                            0 as xmlChar,
